/* Kill the homing shot's 17 trail particles, and if enabled spawn its end burst effects. */
void clear_homing_shot_trail_and_spawn_end_effects(u8 *m, s32 enabled)
{
    s32 i;
    s32 j;
    void **handle;
    u8 *pos;
    Vec4 vectors[2];
    s32 lifetime;
    s32 color;
    s32 sign;
    u8 *effect;
    s32 alpha;

    handle = (void **)(((u8 *)((Moby *)m)->pvars) + 0x2c);
    for (i = 16; i >= 0; i--) {
        if (*handle != 0)
            KillPart(*handle);
        *handle++ = 0;
    }
    pos = m + 0x10;

    if (enabled != 0) {
        Vec4 *vector = &vectors[1];
        for (j = 4; j >= 0; j--) {
            vectors[1].q = 0;
            vectors[1].f[0] = random_float_between(-1.0f, 1.0f);
            vectors[1].f[1] = random_float_between(-1.0f, 1.0f);
            vectors[1].f[2] = random_float_between(-1.0f, 1.0f);
            vectors[0].q = vectors[1].q;
            vec_scale_to_length(vector, &vectors[0],
                random_float_between(g_frame_time * 3.0f, g_frame_time * 6.0f));
            lifetime = rand_range(scale_ticks(10), scale_ticks(15));
            PartType27Spawn(pos, vector, 0x7f2f4f6f, lifetime, 35000.0f);
        }
    }

    {
        s32 j;
        for (j = 2; j >= 0; j--) {
            color = ((u32)rand_range(0x20, 0x80) << 24) | 0x606060;
            sign = random_integer_below(2) ? -1 : 1;
            vectors[0].q = 0;
            vectors[0].f[2] = 1.0f;
            vectors[0].f[3] = 1.0f;
            vectors[0].f[2] = random_float_between(0.01f, 0.025f) * frame_scale;
            effect = PartType23Spawn(pos, sign, 0.2f, 1.0f, &vectors[0], color, 1.02f, 140000.0f);
            if (effect != 0) {
                *(s16 *)(effect + 0xa) = scale_ticks(rand_range(50, 80));
                i = (s32)(effect + 0x20);
                *(s32 *)(i + 4) = 2;
                ((u8 *)i)[0xa] = color >> 24;
                ((u8 *)i)[0xb] = effect[0xa];
                alpha = random_integer_below(2);
                if (alpha) {
                    alpha = 0x44;
                    effect[3] = alpha;
                }
            }
        }
    }
}
