/* Finds the best-scoring target moby in the target list within range and angle limits. */
char *select_ryno_target(float *pos, float *lim, int *skip, float maxy, float maxp, float maxd) {
    char *best = 0;
    float bestScore = 1e9f;
    int i = 0;
    char *m = (char *)active_mobies[0];
    while (m != 0) {
        int n = i + 1;
        if (*(short *)(m + 0x32) != 0) {
            if (skip != 0) {
                int found = 0;
                int k;
                for (k = 0; k < 7; k++) {
                    if (skip[k] == (int)m) { found = 1; break; }
                }
                if (found) goto next;
            } else if (*(unsigned char *)(m + 0x31) == 0) {
                goto next;
            }
            {
                float *r = (float *)GetFlaggedPvarWord(m);
                if (r != 0 && !(r[0] < 0.0f) && (*(unsigned short *)(m + 0x34) & 0x1000) && m != 0
                    && *(int *)(m + 0x24) != 0 && *(short *)(*(int *)(m + 0x24) + 0x46) == 5) {
                    float e;
                    float *p = (float *)(m + 0x10);
                    float d = vec_distance_xy(pos, p);
                    if (d < maxd) {
                        float v[4];
                        float a, b, g;
                        int t, u;
                        qcopy(v, p);
                        v[2] = v[2] + (r[4] + 0.1f);
                        a = fast_atan2(v[0] - pos[0], v[1] - pos[1]);
                        a = FastDiffRots(lim[2], a);
                        e = a * a;
                        if (e < maxy * maxy) {
                            b = fast_atan2(d, v[2] - pos[2]);
                            b = FastDiffRots(lim[1], b);
                            g = b * b;
                            if (g < maxp * maxp) {
                                if (d > 5.0f) { e = e * g * d; e = e + d; }
                                else e = d / 5.0f;
                                if (e < bestScore) {
                                    if (coll_line(pos, v, 2, (int)m, 0) != 0) {
                                        t = coll_hit_result[6];
                                        if (t == 0) goto next;
                                        if ((u = *(int *)(t + 0x24)) != 0 && *(short *)(u + 0x46) == 5) goto accept;
                                        if ((u = *(int *)(t + 0x24)) == 0 || *(short *)(u + 0x46) != 0xF) goto next;
                                    }
                                accept:
                                    bestScore = e;
                                    best = m;
                                }
                            }
                        }
                    }
                }
            }
        }
    next:
        {
            int *pp = active_mobies;
            i = n;
            m = (char *)pp[i];
        }
    }
    return best;
}
